def apply_graph_result(self, graph_result) -> None:
    rows = graph_result.rows
    # Pre-compute per-row max column so graph width can be cached without
    # rescanning edges_to_parent in every paint() / sizeHint() call.
    row_max_cols: list[int] = []
    for row in rows:
        max_col = row.commit_column
        for edge in row.edges_to_parent:
            if edge.from_column > max_col:
                max_col = edge.from_column
            if edge.to_column > max_col:
                max_col = edge.to_column
        row_max_cols.append(max_col)

    oid_to_index: dict[str, int] = {row.commit_oid: i for i, row in enumerate(rows)}

    lane_w = GraphDelegate.LANE_WIDTH
    font_metrics = self.fontMetrics()
    # Use the oidmap (already maintained on insert) instead of scanning the
    # entire tree; this turns O(N*M) into O(M) per chunk.
    summary_col = CommitTreeWidgetItem.SUMMARY
    for oid, row_idx in oid_to_index.items():
        item = self.oidmap.get(oid)
        if item is None or not isinstance(item, CommitTreeWidgetItem):
            continue
        if item.commit.oid != oid:
            # Defensive: the oidmap also stores tag aliases; skip those.
            continue
        row = rows[row_idx]
        item.setData(summary_col, GRAPH_ROW_ROLE, row)
        item.setData(summary_col, COMMIT_ROLE, item.commit)
        if row_idx > 0:
            item.setData(summary_col, GRAPH_PREV_ROW_ROLE, rows[row_idx - 1])
            combined_max = max(row_max_cols[row_idx], row_max_cols[row_idx - 1])
        else:
            combined_max = row_max_cols[row_idx]
        graph_width = (combined_max + 1) * lane_w
        item.setData(summary_col, GRAPH_WIDTH_ROLE, graph_width)
        commit = item.commit
        if commit and commit.tags:
            labels_width = self.graph_delegate._labels_width(
                font_metrics, commit.tags
            )
        else:
            labels_width = 0
        item.setData(summary_col, LABELS_WIDTH_ROLE, labels_width)
    # Resize column to fit content after graph data is loaded.
    if self._column_init_state < ColumnInitState.GRAPH:
        self._column_init_state = ColumnInitState.GRAPH
        self.resizeColumnToContents(CommitTreeWidgetItem.SUMMARY)

